import sys

def solve(x):
    s, n, best = 0.0, 0, (None, None, None)
    while True:
        n += 1
        s += 1 / n
        diff = abs(x - s)
        if best[0] is None or diff < best[0]:
            best = (diff, s, n)
        if s > x + 1:
            return best[1], best[2]

s_val, n_val = solve(float(sys.stdin.read().split()[0]))
print(f"{s_val:.6f} {n_val}")

