import sys
from math import isqrt


def is_perfect(x):
    if x <= 1:
        return False
    total = 0
    for d in range(1, isqrt(x) + 1):
        if x % d == 0:
            total += d
            q = x // d
            if q != x and q != d:
                total += q
    return total == x


