# 六个等级固定输出一遍：先算好每个人的位置，再按模板拼每一行
import sys

grades = {lv: [] for lv in "ABCDEF"}
for line in sys.stdin.read().splitlines():
    line = line.strip()
    if line == "#":
        break
    if line:
        sid, lv = line.split()
        grades[lv].append(sid)

out = []
for lv in "ABCDEF":
    out.append("等级%s: %d人" % (lv, len(grades[lv])))
    if grades[lv]:
        out.append("   分别是：" + "".join("  %s" % sid for sid in grades[lv]) + "  ")
print("\n".join(out))
